/* From Uiverse.io by kennyotsu-monochromia - Tags: card, theme, monochromia, palette */
.__UIV_SCOPE__ .card {
  width: 400px;
  height: 350px;
  --black: #000000;
  --ch-black: #141414;
  --eer-black: #1b1b1b;
  --night-rider: #2e2e2e;
  --white: #ffffff;
  --af-white: #f3f3f3;
  --ch-white: #e1e1e1;
  font-family: Helvetica, sans-serif;
}

.__UIV_SCOPE__ .wrapper {
  margin: 2rem auto;
  width: 250px;
  font-size: small;
}

.__UIV_SCOPE__ .title {
  text-align: center;
  color: #1b1b1b;
}

.__UIV_SCOPE__ .heading {
  font-weight: bold;
  letter-spacing: 7px;
  font-size: 1.5rem;
  position: relative;
  margin-bottom: 6px;
}

.__UIV_SCOPE__ .heading::before {
  content: '';
  position: absolute;
  inset: 0;
  background: #e8e8e8;
  z-index: -1;
  filter: blur(50px);
  height: 50px;
}

.__UIV_SCOPE__ .color {
  padding: 10px 20px;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
}

.__UIV_SCOPE__ .hex {
  text-align: end;
  font-family: monospace;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .black {
  background: var(--black);
  color: var(--ch-white);
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
}

.__UIV_SCOPE__ .eerie-black {
  background: var(--ch-black);
  color: var(--ch-white);
}

.__UIV_SCOPE__ .chinese-black {
  background: var(--eer-black);
  color: var(--ch-white);
}

.__UIV_SCOPE__ .night-rider {
  background: var(--night-rider);
  color: var(--ch-white);
}

.__UIV_SCOPE__ .chinese-white {
  background: var(--ch-white);
  color: var(--night-rider);
}

.__UIV_SCOPE__ .anti-flash-white {
  background: var(--af-white);
  color: var(--night-rider);
}

.__UIV_SCOPE__ .white {
  background: var(--white);
  color: var(--night-rider);
  border-bottom-left-radius: 5px;
  border-bottom-right-radius: 5px;
}

.__UIV_SCOPE__ .border {
  color: var(--night-rider);
  padding: 10px 10px;
  text-align: center;
}

.__UIV_SCOPE__ .border span {
  border-radius: 5px;
  color: var(--ch-white);
  padding: 2px 4px;
  background-color: var(--night-rider);
}
